DROP DATABASE IF EXISTS flight_4;
CREATE DATABASE flight_4;
ALTER SESSION SET CURRENT_DATABASE = 'flight_4';

CREATE TABLE routes (
   rid INTEGER,
   dst_apid INTEGER,
   dst_ap TEXT,
   src_apid BIGINT,
   src_ap TEXT,
   alid BIGINT,   
   airline TEXT,  
   codeshare TEXT
);


CREATE TABLE airports (
   apid INTEGER,
   name TEXT,
   city TEXT,
   country TEXT,
   x DOUBLE,
   y DOUBLE,
   elevation BIGINT,
   iata TEXT,
   icao TEXT 
);


CREATE TABLE airlines (
   alid INTEGER,
   name TEXT,
   iata TEXT,
   icao TEXT,
   callsign TEXT,
   country TEXT,
   active TEXT);

